SELECT
    id,
    user_id AS userId,
    tenant_id AS tenantId,
    resource,
    action,
    resource_id AS resourceId,
    old_value AS oldValue,
    new_value AS newValue,
    ip_address AS ipAddress,
    user_agent AS userAgent,
    status,
    error_message AS errorMessage,
    created_at AS createdAt
FROM audit_logs


        AND tenant_id = #{tenantId}


        AND user_id = #{userId}


        AND resource = #{resource}


        AND resource_id = #{resourceId}


        AND action = #{action}


        AND status = #{status}


        AND status IN

            #{item}



        AND (
            resource LIKE #{search}
            OR action LIKE #{search}
            OR CAST(resource_id AS CHAR) LIKE #{search}
            OR ip_address LIKE #{search}
        )


        AND created_at >= #{startDate}


        AND created_at <= #{endDate}


ORDER BY created_at DESC

    LIMIT #{offset}, #{limit}


    LIMIT #{limit}

SELECT COUNT(*)
FROM audit_logs


        AND tenant_id = #{tenantId}


        AND user_id = #{userId}


        AND resource = #{resource}


        AND resource_id = #{resourceId}


        AND action = #{action}


        AND status = #{status}


        AND status IN

            #{item}



        AND (
            resource LIKE #{search}
            OR action LIKE #{search}
            OR CAST(resource_id AS CHAR) LIKE #{search}
            OR ip_address LIKE #{search}
        )


        AND created_at >= #{startDate}


        AND created_at <= #{endDate}

SELECT
    action,
    COUNT(*) as count
FROM audit_logs


        AND tenant_id = #{tenantId}


        AND created_at >= #{startDate}


        AND created_at <= #{endDate}


GROUP BY action
ORDER BY count DESC

SELECT
    resource,
    COUNT(*) as count
FROM audit_logs


        AND tenant_id = #{tenantId}


        AND created_at >= #{startDate}


        AND created_at <= #{endDate}


GROUP BY resource
ORDER BY count DESC
